[Form]
public class TFMNewPageFromProcess extends FormRun
{
    TFMPageUnplannedItemRegistration                page;
    TFMPageUnplannedItemRegistrationConfiguration   config;
    TFMProcessTable processTable;
    boolean                                         makeNewProcess;
}

public void createNewPage()
{
    page.parmId(PageName.text());
    page.parmTitle(TFMPage_Title.text());
    page.parmIcon(TFMPage_Icon.text());
    if (TFMPagesProvider::getAllPages().getPage(page.parmId()))
    {
        throw Error ('Page name already exist');
    }
    if (makeNewProcess)
    {
        FormRun fr = element.args().caller();

        fr.saveNewProcess(PageName.text(), page.parmTitle(TFMPage_Title.text()));
        config.parmType(PageName.text());

    }
    ttsbegin;
    TFMDeltaPages::createFromPageClass(page);
    TFMPageConfigParms::CreateOrUpdateParameter(page.parmId(),classId2Name(classIdGet(config)),methodStr(TFMPageUnplannedItemRegistrationConfiguration, parmType),config.parmType());
    ttscommit;
    TFMPagesProvider::instance().invalidateProvider();
    if (makeNewProcess)
    {
        return;
    }
    page = TFMPagesProvider::getAllPages().getPage(page.parmId());
    MenuFunction menuFunction = new MenuFunction(menuItemDisplayStr(TFMPageConfigurator), MenuItemType::Display);

    menuFunction.run(new Args(this));

}

public void updatePageIconOnForm()
{
    TFMGraphicsHelper::setImageHtmlWithWidth(page.parmIcon(), HtmlViewerIcon, 120); //TODO: Use the TFMMediaProvider getMediaForHtml
}

public void init()
{
    page    = new TFMPageUnplannedItemRegistration();
    config  = page.getConfiguration();
    processTable = element.args().record();        
    config.parmType(processTable.ProcessID);
    page.parmFilter(processTable.ProcessID + 'Header');
    super();
    FormStringControl fst = element.design().controlName(formControlStr(TFMNewPageFromProcess, PageName));
    fst.text(processTable.ProcessID);
    fst = element.design().controlName(formControlStr(TFMNewPageFromProcess, TFMPage_Title));
    fst.text(TFMHelper::convertCamelCaseToNiceText(processTable.ProcessID));
    fst = element.design().controlName(formControlStr(TFMNewPageFromProcess, TFMPage_Icon));
    page.parmIcon(fst.text(resourceStr(TFMTaskletLogo)));
    this.updatePageIconOnForm();
    Set pages = TFMPagesProvider::getAllPages().getPagesUsingProcess(processTable.ProcessID);
    if (pages.elements())
    {
        FormStaticTextControl fstt = ExistingPageGroup.addControl(FormControlType::StaticText, 'processisusedonpage');
        str                     pagesWithProcess = "@TFM:TheProcessisalreadyusedonthesepa" + TFMConstants::lineBreak();
        SetEnumerator sEnum = pages.getEnumerator();
        while (sEnum.moveNext())
        {
            TFMPage localpage = sEnum.current();
            pagesWithProcess += TFMListVisualization::getMenuTitle(localpage.parmTitle())+ TFMConstants::lineBreak();
        }
        fstt.text(pagesWithProcess);
        FormCheckBoxControl fcbc = ExistingPageGroup.addControl(FormControlType::CheckBox, 'createnewProcess');
        fcbc.label("@TFM:Createnewprocessforthispage");
        fcbc.value(1);
        fcbc.registerOverrideMethod(methodStr(FormCheckBoxControl, modified), formmethodStr(TFMNewPageFromProcess,control_modified ), this);
        makeNewProcess = true;
    }
}

public boolean control_modified(FormControl _control)
{
    FormCheckBoxControl cbControl = _control;
    makeNewProcess = cbControl.value();
    return true;
}

public boolean modified()
{
    boolean ret;

    ret = super();
    page.parmId(this.text());

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public boolean modified()
{
    boolean ret;

    ret = super();
    page.parmTitle(this.text());
    TFMPage_TitleTranslated.text(TFMListVisualization::getMenuTitle(page.parmTitle()));
    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public boolean modified()
{
    boolean ret;

    ret = super();
    page.parmIcon(this.text());

    element.updatePageIconOnForm();

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public boolean modified()
{
    boolean ret;

    ret = super();
    page.parmAvailableForMenuPages(this.value());

    return ret;
}
